func (q *Queries) ListUploadsAdmin(ctx context.Context, arg ListUploadsAdminParams) ([]Analysis, error) {
	rows, err := q.db.Query(ctx, listUploadsAdmin,
		arg.Limit,
		arg.Offset,
		arg.IncludeDeleted,
		arg.Search,
		arg.StatusFilter,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Analysis{}
	for rows.Next() {
		var i Analysis
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ProjectID,
			&i.UserID,
			&i.Keyword,
			&i.KeywordNormalized,
			&i.ThumbnailS3Key,
			&i.Status,
			&i.Score,
			&i.VisibilityScore,
			&i.ContrastScore,
			&i.AttentionScore,
			&i.MobileScore,
			&i.BrandingScore,
			&i.CuriosityScore,
			&i.CvResults,
			&i.CompetitorAvg,
			&i.Suggestions,
			&i.CompetitorCount,
			&i.RankInCompetitors,
			&i.ErrorMessage,
			&i.RetryCount,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.RelevanceScore,
			&i.RelevanceReasoning,
			&i.ActualCtr,
			&i.PublishedAt,
			&i.FileSizeBytes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

