const listUsersAdmin = `-- name: ListUsersAdmin :many

SELECT
    u.id, u.email, u.password_hash, u.full_name, u.avatar_url, u.google_id, u.email_verified, u.stripe_customer_id, u.created_at, u.updated_at, u.deleted_at, u.status,
    COALESCE(ws.plan, '') AS plan,
    COALESCE(agg.analyses_count, 0)::bigint AS analyses_count,
    COALESCE(agg.storage_used, 0)::bigint AS storage_used
FROM users u
LEFT JOIN LATERAL (
    SELECT w.plan FROM workspace_members wm
    JOIN workspaces w ON w.id = wm.workspace_id AND w.deleted_at IS NULL
    WHERE wm.user_id = u.id
    ORDER BY wm.joined_at ASC
    LIMIT 1
) ws ON true
LEFT JOIN LATERAL (
    SELECT COUNT(*) AS analyses_count, COALESCE(SUM(file_size_bytes), 0) AS storage_used
    FROM analyses
    WHERE analyses.user_id = u.id AND analyses.deleted_at IS NULL
) agg ON true
WHERE u.deleted_at IS NULL
  AND ($3::text = '' OR u.email ILIKE '%' || $3 || '%' OR u.full_name ILIKE '%' || $3 || '%')
  AND ($4::text = '' OR u.status = $4)
ORDER BY u.created_at DESC
LIMIT $1 OFFSET $2
`

type ListUsersAdminParams struct {
	Limit        int32  `json:"limit"`
	Offset       int32  `json:"offset"`
	Search       string `json:"search"`
	StatusFilter string `json:"status_filter"`
}

type ListUsersAdminRow struct {
	ID               uuid.UUID          `json:"id"`
	Email            string             `json:"email"`
	PasswordHash     pgtype.Text        `json:"password_hash"`
	FullName         string             `json:"full_name"`
	AvatarUrl        pgtype.Text        `json:"avatar_url"`
	GoogleID         pgtype.Text        `json:"google_id"`
	EmailVerified    bool               `json:"email_verified"`
	StripeCustomerID pgtype.Text        `json:"stripe_customer_id"`
	CreatedAt        pgtype.Timestamptz `json:"created_at"`
	UpdatedAt        pgtype.Timestamptz `json:"updated_at"`
	DeletedAt        pgtype.Timestamptz `json:"deleted_at"`
	Status           string             `json:"status"`
	Plan             string             `json:"plan"`
	AnalysesCount    int64              `json:"analyses_count"`
	StorageUsed      int64              `json:"storage_used"`
}

// User management ---------------------------------------------------------
//
// ListUsersAdmin/GetUserDetailAdmin fold each user's primary-workspace plan
// and analyses/storage totals into the same query via LATERAL joins, instead
// of issuing 2-3 extra round-trips per user (avoids N+1 on the paginated
// list).
func (q *Queries) ListUsersAdmin(ctx context.Context, arg ListUsersAdminParams) ([]ListUsersAdminRow, error) {
	rows, err := q.db.Query(ctx, listUsersAdmin,
		arg.Limit,
		arg.Offset,
		arg.Search,
		arg.StatusFilter,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUsersAdminRow{}
	for rows.Next() {
		var i ListUsersAdminRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.PasswordHash,
			&i.FullName,
			&i.AvatarUrl,
			&i.GoogleID,
			&i.EmailVerified,
			&i.StripeCustomerID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.Status,
			&i.Plan,
			&i.AnalysesCount,
			&i.StorageUsed,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const monthlySignupTrend = `-- name: MonthlySignupTrend :many
SELECT date_trunc('month', created_at)::date AS bucket, COUNT(*) AS count
FROM users
WHERE deleted_at IS NULL AND created_at >= NOW() - interval '12 months'
GROUP BY bucket
ORDER BY bucket
`

type MonthlySignupTrendRow struct {
	Bucket pgtype.Date `json:"bucket"`
	Count  int64       `json:"count"`
}

func (q *Queries) MonthlySignupTrend(ctx context.Context) ([]MonthlySignupTrendRow, error) {
	rows, err := q.db.Query(ctx, monthlySignupTrend)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MonthlySignupTrendRow{}
	for rows.Next() {
		var i MonthlySignupTrendRow
		if err := rows.Scan(&i.Bucket, &i.Count); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

